import {createGame,reducer,evaluateMove,visibleViewport,invariants,PUZZLES,RULES,autoInterval} from './cluster-model.js';
const $=id=>document.getElementById(id),canvas=$('board'),ctx=canvas.getContext('2d');
const storage={get(k,f){try{return localStorage.getItem(k)??f}catch{return f}},set(k,v){try{localStorage.setItem(k,String(v))}catch{}}};
let mode='endless',puzzleId=PUZZLES[0].id,seed=314159,state,started=false,paused=false,practice=false,eligible=true,direction='right',timer=null,history=[],combo=0,lastCollectStep=-100,best=Number(storage.get('tjz-cluster-best','0'))||0;
let reduced=storage.get('tjz-cluster-motion','')==='reduce'||matchMedia('(prefers-reduced-motion: reduce)').matches;
let camera={x:0,y:0},anim=null,lastFrame=0,view=null,flashTimer=null,raf=null;
const dirs={ArrowUp:'up',ArrowRight:'right',ArrowDown:'down',ArrowLeft:'left',w:'up',d:'right',s:'down',a:'left'};
const sign=n=>(n>0?'+':'')+Number(n).toFixed(1),level=()=>Math.min(8,1+Math.floor((state.chain.length-1)/3));
const period=()=>autoInterval(state);
function stopTimer(){clearTimeout(timer);timer=null;}
function schedule(){stopTimer();if(started&&!paused&&!practice&&mode==='endless'&&state.status==='running')timer=setTimeout(()=>{if(document.hidden||document.visibilityState==='hidden'||(typeof document.hasFocus==='function'&&!document.hasFocus())){pause('页面不在前台，已为你暂停。回来后手动继续。');return;}move(direction);schedule()},period());}
function overlay(kicker,title,copy,button){$('overlay').hidden=false;$('overlay-kicker').textContent=kicker;$('overlay-title').textContent=title;$('overlay-copy').textContent=copy;$('start').textContent=button;$('next').hidden=!(state.status==='won'&&PUZZLES.findIndex(p=>p.id===puzzleId)<PUZZLES.length-1);}
function fresh(){stopTimer();clearTimeout(flashTimer);$('collect-flash').classList.remove('pop');state=createGame({mode,seed,puzzleId});started=false;paused=false;history=[];combo=0;lastCollectStep=-100;direction='right';eligible=!practice;anim=null;camera={...state.head};$('seed').value=seed;
 $('mode-endless').setAttribute('aria-pressed',String(mode==='endless'));$('mode-puzzle').setAttribute('aria-pressed',String(mode==='puzzle'));$('level-section').hidden=mode!=='puzzle';$('undo').hidden=mode!=='puzzle';$('practice').closest('label').hidden=mode==='puzzle';$('new-world').disabled=mode==='puzzle';$('seed-apply').disabled=mode==='puzzle';$('seed').disabled=mode==='puzzle';
 notice(mode==='puzzle'?'先按开始，再逐步把所有空穴接进队伍。':'先按开始。方向键 / WASD 转向，R 换头，空格暂停。');
 document.querySelectorAll('[data-level]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.level===puzzleId)));
 const p=PUZZLES.find(p=>p.id===puzzleId);overlay(mode==='endless'?'ONE HOLE. A WHOLE WORLD.':'PUZZLE / '+p.name,mode==='endless'?'从一个洞，长成一条队伍。':p.name,mode==='endless'?'靠近金色空穴，把它接进队伍。方向键转向，R 换头；电池耗尽或没有合法路线时结束。':p.description+` 收齐 ${p.holes.length} 个洞，中间态相对能量不得超过 ${p.cap} Jz。`,mode==='endless'?'开始冲分 →':'开始解谜 →');update();}
function start(){if(state.status==='won'||state.status==='lost'){fresh();}started=true;paused=false;state=reducer(state,{type:'resume'});$('overlay').hidden=true;notice(mode==='puzzle'?'点方向走一步。收齐全部空穴，始终不超过能量上限。':practice?'步进练习中：每次方向输入只走一步，不计最佳纪录。':'已出发。方向键转向；前方被挡会自动暂停，选择新路线再继续。');update();schedule();canvas.focus({preventScroll:true});}
function notice(s){$('notice').textContent=s;}
function pause(reason='已暂停。点击继续，或空格继续。'){if(!started||['won','lost'].includes(state.status))return;paused=true;stopTimer();state=reducer(state,{type:'pause'});anim=null;overlay('TAKE A BREATH.','暂停在这里。',reason,'继续 →');notice(reason);update();}
function togglePause(){if(!started){start();return;}if(paused){start();return;}pause();}
function recordBest(){if(mode==='endless'&&eligible&&state.score>best){best=state.score;storage.set('tjz-cluster-best',best);}}
function move(dir){if(!started||paused||state.status!=='running')return;direction=dir;const before=state,result=evaluateMove(state,dir);
 if(mode==='puzzle'&&result.ok){history.push(state);if(history.length>500)history.shift();}
 state=reducer(state,{type:'move',dir});
 if(!result.ok){notice(state.event);if(mode==='endless'&&!practice)pause(state.event+' 换个方向或按 R 换头后再继续。');update();return;}
 if(result.kind==='hop'&&!reduced)anim={start:performance.now(),duration:Math.min(360,period()*.65),hops:result.subhops};
 if(state.collected>before.collected){combo=state.steps-lastCollectStep<=7?combo+1:1;lastCollectStep=state.steps;const flash=$('collect-flash');flash.textContent=`+${RULES.scorePerHole}  ·  LENGTH ${state.chain.length}`;flash.classList.remove('pop');void flash.offsetWidth;flash.classList.add('pop');clearTimeout(flashTimer);flashTimer=setTimeout(()=>flash.classList.remove('pop'),850);recordBest();}
 if(state.steps-lastCollectStep>7)combo=0;
 notice(result.kind==='hop'?`${state.chain.length} 洞协同 · ${result.subhops.length} 次近邻交换 · 本步 ΔE ${sign(result.delta)} Jz · 中途峰值 ${sign(result.peak)} Jz`:state.event);
 if(state.status==='won'){stopTimer();storage.set('tjz-puzzle-'+puzzleId,'won');renderLevels();overlay('ALL HOLES TOGETHER.','这一团，齐了。',`全部 ${state.chain.length} 个空穴连成一条。${state.hops} 次真实交换，峰值 ${sign(state.peak)} / ${state.limit} Jz。`,'再解一次 ↻');}
 if(state.status==='lost'){stopTimer();recordBest();notice(state.event);overlay('A GOOD RUN.','这次，到这里。',state.event+` 得分 ${state.score}，控制长度 ${state.chain.length}。同一种子可以重走另一条路线。`,'同种子再来 ↻');}
 update();}
function reverse(){if(!started||['won','lost'].includes(state.status))return;if(mode==='puzzle')history.push(state);const wasPaused=paused;state=reducer({...state,status:'running'},{type:'reverse'});if(wasPaused)state=reducer(state,{type:'pause'});anim=null;
 // Point away from the new neck when possible, rather than immediately hitting the body.
 if(state.chain.length>1){const [h,n]=state.chain;direction=h.x>n.x?'right':h.x<n.x?'left':h.y>n.y?'down':'up';}
 notice(state.event);if(wasPaused)$('overlay-copy').textContent='已换到另一端。点击继续，或先选择新的方向。';update();}
function update(){const p=PUZZLES.find(p=>p.id===puzzleId),inv=invariants(state);$('score').textContent=String(state.score).padStart(4,'0');$('best').textContent=best;$('length').textContent=mode==='puzzle'?`${state.chain.length} / ${p.holes.length}`:state.chain.length;$('rank').textContent=String(level()).padStart(2,'0');$('combo').textContent='×'+Math.max(1,combo);$('energy').textContent=sign(state.energy);$('delta').textContent=sign(state.lastDelta||0);$('peak').textContent=`${sign(state.peak)} / ${state.limit}`;$('swaps').textContent=state.hops;$('coordinates').textContent=`${state.head.x}, ${state.head.y}`;
 $('world-label').textContent=mode==='endless'?'∞ 无界晶格 · 按需生成':`◇ ${p.name} · ${p.holes.length} 个有限空穴`;$('speed-label').textContent=mode==='puzzle'?'PUZZLE · 逐步思考':practice?'PRACTICE · 不计纪录':`巡航 ${level()} · ${(1000/period()).toFixed(1)} 格/秒`;
 $('compact-label').textContent=(mode==='endless'?'电池':'峰值上限')+` · E ${sign(state.energy)} Jz`;$('compact-value').textContent=mode==='endless'?state.battery.toFixed(1):`${state.limit} Jz`;
 $('resource-label').textContent=mode==='endless'?'ARCADE BATTERY':'PEAK ENERGY BUDGET';$('resource-value').textContent=mode==='endless'?state.battery.toFixed(1):`${state.limit} Jz`;$('battery-meter').style.width=mode==='endless'?`${100*state.battery/state.batteryMax}%`:`${state.limit?Math.max(0,100*(state.limit-state.peak)/state.limit):100}%`;
 $('resource-copy').textContent=mode==='endless'?`聚团 +${RULES.collectionCharge}；每步电池扣费按链长平均。独立游戏资源，交换能不做平均。`:'每一个中间态都必须在上限内。超限动作原地挡回，可撤销后换一条路线。';
 $('conservation').textContent=Object.values(inv).every(v=>v===0)?'ΔN↑ = ΔN↓ = ΔNₕ = 0':'守恒校验异常，请重开';$('world-note').textContent=mode==='endless'?`镜头是视区，不是围墙。已修改 ${Object.keys(state.world.overrides).length} 个格点，离开后仍保留。`:`这关总共 ${p.holes.length} 个空穴；聚团只是增加控制长度，不删除任何洞。`;
 $('pause').textContent=paused?'▶ 继续':'Ⅱ 暂停';$('undo').disabled=history.length===0;$('step').disabled=!started||paused||state.status!=='running';$('reverse').disabled=!started||['won','lost'].includes(state.status);document.querySelectorAll('[data-dir]').forEach(b=>{const result=evaluateMove({...state,status:'running'},b.dataset.dir);b.title=result.ok?`ΔE ${sign(result.delta)} · 峰值 ${sign(result.peak)} Jz`:'这条路被挡住，换一端或另一方向';});}
function renderLevels(){document.querySelector('.section-label b').textContent=`${PUZZLES.length} 道晶格谜题`;$('levels').replaceChildren(...PUZZLES.map((p,i)=>{const b=document.createElement('button');b.dataset.level=p.id;b.setAttribute('aria-pressed',String(puzzleId===p.id));const n=document.createElement('span');n.textContent=`${String(i+1).padStart(2,'0')} / ${storage.get('tjz-puzzle-'+p.id,'')==='won'?'已完成 ✓':'待解'}`;const title=document.createElement('b');title.textContent=p.name.replace(/^\d+\s*·\s*/,'');const small=document.createElement('small');small.textContent=`${p.holes.length} 洞 · 上限 ${p.cap} Jz`;b.append(n,title,small);b.onclick=()=>{puzzleId=p.id;fresh()};return b;}));}
function draw(t){const box=canvas.getBoundingClientRect();if(!box.width||!box.height){raf=requestAnimationFrame(draw);return;}const dpr=Math.min(2,devicePixelRatio||1);if(canvas.width!==Math.round(box.width*dpr)||canvas.height!==Math.round(box.height*dpr)){canvas.width=Math.round(box.width*dpr);canvas.height=Math.round(box.height*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);const w=box.width,h=box.height,cell=w<500?34:43;
 const dt=Math.min(60,t-lastFrame||16);lastFrame=t;const follow=reduced?1:1-Math.exp(-dt/115);camera.x+=(state.head.x-camera.x)*follow;camera.y+=(state.head.y-camera.y)*follow;
 const px=x=>w/2+(x-camera.x)*cell,py=y=>h/2+(y-camera.y)*cell;ctx.fillStyle='#172f28';ctx.fillRect(0,0,w,h);
 const cols=Math.ceil(w/cell)+3,rows=Math.ceil(h/cell)+3;view=visibleViewport(state,{x:Math.floor(camera.x-cols/2),y:Math.floor(camera.y-rows/2),width:cols,height:rows});
 for(const c of view.cells){const x=px(c.x),y=py(c.y);ctx.fillStyle=((c.x+c.y)%2===0)?'#1b332b':'#1e372d';ctx.fillRect(x-cell/2,y-cell/2,cell,cell);ctx.strokeStyle='#a9bb9820';ctx.lineWidth=.6;ctx.strokeRect(x-cell/2,y-cell/2,cell,cell);}
 for(const b of view.bonds){if(!b.frustrated)continue;ctx.beginPath();ctx.moveTo(px(b.a.x),py(b.a.y));ctx.lineTo(px(b.b.x),py(b.b.y));ctx.strokeStyle='#cb86574a';ctx.lineWidth=3;ctx.stroke();}
 // A wide connected ribbon sits behind individual, physically empty sites.
 if(state.chain.length>1){ctx.beginPath();state.chain.forEach((p,i)=>i?ctx.lineTo(px(p.x),py(p.y)):ctx.moveTo(px(p.x),py(p.y)));ctx.strokeStyle='#d8ee9a38';ctx.lineWidth=cell*.62;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();ctx.strokeStyle='#c9e99b';ctx.lineWidth=2;ctx.stroke();}
 ctx.textAlign='center';ctx.textBaseline='middle';
 for(const c of view.cells){const x=px(c.x),y=py(c.y);if(c.value===0){const own=c.chainIndex>=0,head=c.chainIndex===0;ctx.beginPath();ctx.arc(x,y,cell*(head?.30:own?.26:.22),0,Math.PI*2);ctx.fillStyle=own?'#1a3126':'#182d25';ctx.fill();ctx.strokeStyle=own?'#d8ee9a':'#ecc680';ctx.lineWidth=head?3:own?2:1.7;ctx.stroke();if(head){ctx.beginPath();ctx.arc(x,y,cell*.39,0,Math.PI*2);ctx.strokeStyle='#d8ee9a70';ctx.lineWidth=1;ctx.stroke();const v={up:[0,-1],right:[1,0],down:[0,1],left:[-1,0]}[direction];ctx.fillStyle='#e8f6be';ctx.beginPath();ctx.arc(x+v[0]*cell*.09,y+v[1]*cell*.09,3.5,0,Math.PI*2);ctx.fill();}else if(own){ctx.fillStyle='#b3cd87';ctx.font=`${cell*.23}px ${getComputedStyle(document.body).fontFamily}`;ctx.fillText(c.chainIndex===state.chain.length-1?'●':'·',x,y);}else{ctx.fillStyle='#ecc680';ctx.font=`${cell*.29}px monospace`;ctx.fillText('+',x,y);}}else{const changed=c.value!==c.reference;ctx.fillStyle=c.value>0?(changed?'#d8db9e':'#7fa891'):(changed?'#e5bda0':'#ad9876');ctx.globalAlpha=changed?.95:.6;ctx.font=`${cell*.40}px Georgia`;ctx.fillText(c.value>0?'↑':'↓',x,y);ctx.globalAlpha=1;}}
 if(anim&&!reduced){const q=(t-anim.start)/anim.duration;if(q>=1)anim=null;else{const pos=q*anim.hops.length,i=Math.min(anim.hops.length-1,Math.floor(pos)),f=pos-i,hop=anim.hops[i];if(hop){const x=px(hop.from.x+(hop.to.x-hop.from.x)*f),y=py(hop.from.y+(hop.to.y-hop.from.y)*f);ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fillStyle='#fff1b8';ctx.shadowColor='#fff1b8';ctx.shadowBlur=14;ctx.fill();ctx.shadowBlur=0;}}}
 raf=requestAnimationFrame(draw);}
function toggleFocus(){const on=document.body.classList.toggle('focus-board');for(const id of ['focus','focus-top']){$(id).setAttribute('aria-pressed',String(on));$(id).textContent=on?'⤡ 退出专注':'⤢ 专注棋盘';}}
$('focus').onclick=toggleFocus;$('focus-top').onclick=toggleFocus;
$('start').onclick=start;$('pause').onclick=togglePause;$('pad-pause').onclick=togglePause;$('reset').onclick=fresh;$('reverse').onclick=reverse;
$('step').onclick=()=>{if(mode==='endless'&&!practice){practice=true;eligible=false;$('practice').checked=true;stopTimer();}move(direction);};
$('undo').onclick=()=>{if(mode!=='puzzle'||!history.length)return;state=history.pop();state={...state,status:'running'};paused=false;started=true;anim=null;$('overlay').hidden=true;notice('已撤销上一动作。');update();};
$('next').onclick=()=>{const i=PUZZLES.findIndex(p=>p.id===puzzleId);if(i<PUZZLES.length-1){puzzleId=PUZZLES[i+1].id;fresh();}};
$('mode-endless').onclick=()=>{mode='endless';fresh();};$('mode-puzzle').onclick=()=>{mode='puzzle';fresh();};
$('practice').onchange=()=>{practice=$('practice').checked;if(practice)eligible=false;notice(practice?'已进入步进练习；这一局不计最佳纪录。':'自动前进已开启；曾进入练习的这一局仍不计纪录。');update();schedule();};
function steer(dir){direction=dir;if(paused){$('overlay-copy').textContent='方向已调整。点击继续出发。';return;}if(!started)return;if(mode==='puzzle'||practice)move(dir);else{move(dir);schedule();}}
for(const b of document.querySelectorAll('[data-dir]'))b.onclick=()=>steer(b.dataset.dir);
window.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;if(e.target.matches('input,select,textarea,summary'))return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(dirs[k]){e.preventDefault();if(!e.repeat)steer(dirs[k]);}else if(k===' '){e.preventDefault();if(!e.repeat)togglePause();}else if(k==='r'&&!e.repeat){e.preventDefault();reverse();}});
let touch=null;canvas.addEventListener('pointerdown',e=>{touch={x:e.clientX,y:e.clientY,id:e.pointerId};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointerup',e=>{if(!touch||touch.id!==e.pointerId)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.max(Math.abs(dx),Math.abs(dy))<16)return;steer(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');});canvas.addEventListener('pointercancel',()=>{touch=null;});
$('seed-apply').onclick=()=>{const val=$('seed').value.trim();if(!/^\d+$/.test(val)||Number(val)>4294967295){notice('请输入 0 到 4294967295 之间的整数种子。');return;}seed=Number(val);fresh();};$('new-world').onclick=()=>{seed=Math.floor(Math.random()*4294967296);fresh();};
function setMotion(){document.body.classList.toggle('reduce-motion',reduced);$('motion').textContent=reduced?'动态 减少':'动态 开';$('motion').setAttribute('aria-pressed',String(reduced));} $('motion').onclick=()=>{reduced=!reduced;storage.set('tjz-cluster-motion',reduced?'reduce':'full');setMotion();};
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause('切到其他页面时已自动暂停。回来后手动继续。');});window.addEventListener('blur',()=>pause('窗口失去焦点，已为你暂停。'));window.addEventListener('pagehide',()=>{pause('离开页面时已暂停。返回后请手动继续。');stopTimer();clearTimeout(flashTimer);cancelAnimationFrame(raf);});window.addEventListener('pageshow',e=>{if(e.persisted){cancelAnimationFrame(raf);raf=requestAnimationFrame(draw);}});
renderLevels();setMotion();fresh();raf=requestAnimationFrame(draw);
